import { useEffect, useRef, useState } from "react";
import { useParams } from "react-router-dom";

// ⬇️ Dùng lại 2 file CSS cũ của bạn
import "../styles/ChatMessage.css";
import "../styles/ChatInput.css";

export default function ChatMain() {
  const { id } = useParams();
  const [text, setText] = useState("");
  const [messages, setMessages] = useState([
    {
      id: 1,
      text: `Chat ${id || "default"} started.`,
      isUser: false,
      timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    },
  ]);

  const listRef = useRef(null);

  // Tự cuộn xuống cuối khi có tin nhắn mới
  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
  }, [messages]);

  const handleSend = (e) => {
    e?.preventDefault();
    if (!text.trim()) return;

    const now = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

    setMessages((prev) => [
      ...prev,
      { id: Date.now(), text, isUser: true, timestamp: now },
      // demo phản hồi AI
      { id: Date.now() + 1, text: `You said: ${text}`, isUser: false, timestamp: now },
    ]);
    setText("");
  };

  return (
    <div className="chat-main" style={{ display: "flex", flexDirection: "column", height: "100%" }}>
      {/* KHU VỰC TIN NHẮN (đặt class trùng CSS cũ để khớp style tổng) */}
      <div className="messages-container" style={{ flex: 1, overflow: "hidden", background: "transparent" }}>
        <div ref={listRef} className="messages-list">
          {messages.map((msg) => (
            <div key={msg.id} className={`message ${msg.isUser ? "user-message" : "ai-message"}`}>
              <div className="message-avatar">
                <span>{msg.isUser ? "U" : "AI"}</span>
              </div>

              <div className="message-content">
                <div className="message-bubble">{msg.text}</div>
                {msg.timestamp && <div className="message-timestamp">{msg.timestamp}</div>}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Ô NHẬP (dùng class cũ: chat-input-form / input-container / message-input / send-button) */}
      <form className="chat-input-form" onSubmit={handleSend}>
        <div className="input-container">
          <input
            className="message-input"
            type="text"
            placeholder="Type your message..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          <button className="send-button" type="submit" disabled={!text.trim()}>
            {/* icon gửi đơn giản */}
            <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true">
              <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
            </svg>
          </button>
        </div>
      </form>
    </div>
  );
}
